// Writes src/lib/server/bundledCatalogue.ts: static imports of every data/brands/*.json file
// (and the DEMO catalogue), so hosts without a file system (Cloudflare Workers) can serve them.
// Runs automatically before `npm run build`.
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const brands = fs.readdirSync(path.join(root, "data/brands")).filter((f) => f.endsWith(".json")).sort();
const ident = (f) => "brand_" + f.replace(/\.json$/, "").replace(/[^a-zA-Z0-9]/g, "_");
const lines = [
  "// Generated by scripts/bundle-catalogue.mjs. Do not edit; run `npm run catalogue:bundle`.",
  ...brands.map((f) => `import ${ident(f)} from "../../../data/brands/${f}";`),
  'import demo from "../../../data/demo-catalogue.json";',
  "",
  "export const BUNDLED_BRAND_FILES: { file: string; data: unknown }[] = [",
  ...brands.map((f) => `  { file: "data/brands/${f}", data: ${ident(f)} },`),
  "];",
  'export const BUNDLED_DEMO_FILE = { file: "data/demo-catalogue.json", data: demo as unknown };',
  "",
];
const out = path.join(root, "src/lib/server/bundledCatalogue.ts");
const next = lines.join("\n");
if (!fs.existsSync(out) || fs.readFileSync(out, "utf8") !== next) fs.writeFileSync(out, next);
console.log(`bundled ${brands.length} brand file(s)`);
